3. What is the output and explain why?
public class Swap {
    static void swap(int a, int b) {
        int temp = a;
        a = b;
        b = temp;
        System.out.println("Inside: a=" + a + ", b=" + b);
    }
    public static void main(String[] args) {
        int x = 5, y = 10;
        swap(x, y);
        System.out.println("Outside: x=" + x + ", y=" + y);
    }
}

5. What is the output?
public class RecursionTrace {
    public static int mystery(int n) {
        if (n == 0) return 0;
        return n + mystery(n - 1);
    }
    public static void main(String[] args) {
        System.out.println(mystery(5));
    }
}

6. Refactor this method using Single Responsibility:
public void handleRegistration(String name, String email, String password) {
    // Validate
    if (name == null || name.isBlank()) throw new IllegalArgumentException("Name required");
    if (!email.contains("@")) throw new IllegalArgumentException("Bad email");
    if (password.length() < 8) throw new IllegalArgumentException("Short password");
    // Create user
    User user = new User(name, email, password);
    userRepo.save(user);
    // Send email
    String body = "Welcome " + name + "! Your account is ready.";
    emailService.send(email, "Welcome!", body);
    // Log
    System.out.println("User registered: " + email);
}
